from __future__ import annotations

"""proto3-style message model with scalar fields and explicit defaults.

A schema is a set of named scalar fields. In proto3 every scalar has an
implicit default: ``0`` for numbers, ``""`` for strings, ``false`` for bools,
and the zero-valued constant for enums. A message instance carries a value for
every field it knows about, plus a record of which fields a caller actually
assigned. That second record matters: a caller can deliberately write a field
back to its default (a price of ``0``, an empty ``name``, ``active=false``),
and that write is just as real as any other.

The data model here keeps both pieces: ``values`` (one entry per field, default
filled in for anything never set) and ``_assigned`` (the names the caller put
there). Code elsewhere folds one message onto another and has to decide, per
field, whether the incoming message carries something to apply.
"""

from dataclasses import dataclass, field
from enum import Enum


class FieldType(Enum):
    INT32 = "int32"
    STRING = "string"
    BOOL = "bool"
    ENUM = "enum"


# proto3 implicit defaults by scalar type.
_DEFAULTS: dict[FieldType, object] = {
    FieldType.INT32: 0,
    FieldType.STRING: "",
    FieldType.BOOL: False,
    FieldType.ENUM: 0,
}


@dataclass(frozen=True)
class FieldDescriptor:
    name: str
    number: int
    field_type: FieldType

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("field name is required")
        if self.number <= 0:
            raise ValueError("field number must be positive")

    def default_value(self) -> object:
        return _DEFAULTS[self.field_type]

    def is_default(self, value: object) -> bool:
        return value == self.default_value()


@dataclass(frozen=True)
class MessageSchema:
    name: str
    fields: tuple[FieldDescriptor, ...]

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("message name is required")
        seen_names: set[str] = set()
        seen_numbers: set[int] = set()
        for descriptor in self.fields:
            if descriptor.name in seen_names:
                raise ValueError(f"duplicate field name {descriptor.name}")
            if descriptor.number in seen_numbers:
                raise ValueError(f"duplicate field number {descriptor.number}")
            seen_names.add(descriptor.name)
            seen_numbers.add(descriptor.number)

    def field(self, name: str) -> FieldDescriptor:
        for descriptor in self.fields:
            if descriptor.name == name:
                return descriptor
        raise KeyError(f"unknown field {name}")

    def has_field(self, name: str) -> bool:
        return any(descriptor.name == name for descriptor in self.fields)

    def field_names(self) -> list[str]:
        return [descriptor.name for descriptor in self.fields]

    def defaults(self) -> dict[str, object]:
        return {descriptor.name: descriptor.default_value() for descriptor in self.fields}


@dataclass
class Message:
    """A message instance plus the set of field names the caller assigned."""

    schema: MessageSchema
    values: dict[str, object] = field(default_factory=dict)
    _assigned: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        merged = self.schema.defaults()
        for name, value in self.values.items():
            if not self.schema.has_field(name):
                raise KeyError(f"unknown field {name}")
            merged[name] = value
        self.values = merged

    def get(self, name: str) -> object:
        if not self.schema.has_field(name):
            raise KeyError(f"unknown field {name}")
        return self.values[name]

    def set(self, name: str, value: object) -> "Message":
        descriptor = self.schema.field(name)
        coerced = _coerce(descriptor.field_type, value)
        self.values[name] = coerced
        self._assigned.add(name)
        return self

    def clear(self, name: str) -> "Message":
        descriptor = self.schema.field(name)
        self.values[name] = descriptor.default_value()
        self._assigned.discard(name)
        return self

    def assigned_fields(self) -> set[str]:
        """Field names the caller explicitly assigned (presence)."""

        return set(self._assigned)

    def was_assigned(self, name: str) -> bool:
        return name in self._assigned

    def copy(self) -> "Message":
        return Message(
            schema=self.schema,
            values=dict(self.values),
            _assigned=set(self._assigned),
        )

    def as_dict(self) -> dict[str, object]:
        return dict(self.values)


def _coerce(field_type: FieldType, value: object) -> object:
    if field_type is FieldType.INT32:
        return int(value)
    if field_type is FieldType.STRING:
        return str(value)
    if field_type is FieldType.BOOL:
        return bool(value)
    if field_type is FieldType.ENUM:
        return int(value)
    raise ValueError(f"unsupported field type {field_type}")


def new_message(schema: MessageSchema, **assignments: object) -> Message:
    """Build a message and mark every passed field as explicitly assigned."""

    message = Message(schema=schema)
    for name, value in assignments.items():
        message.set(name, value)
    return message

