from __future__ import annotations

"""Fold an update message onto a base message.

The merge contract mirrors proto3's ``MergeFrom`` for scalars: any field the
update carries replaces the base's field; any field the update does not carry
leaves the base untouched. The base is never mutated; a new message comes back.

Whether the update "carries" a given field is delegated to the presence layer,
which is shared with the masked-update path so both folds agree.
"""

from field_model import Message
from presence import carries_value, present_fields


def merge(base: Message, update: Message) -> Message:
    """Return a new message: base, with every field the update carries applied."""

    _require_same_schema(base, update)
    result = base.copy()
    for name in update.schema.field_names():
        if carries_value(update, name):
            result.set(name, update.get(name))
    return result


def merge_all(base: Message, updates: list[Message]) -> Message:
    """Fold a sequence of updates onto a base, in order."""

    result = base.copy()
    for update in updates:
        result = merge(result, update)
    return result


def merged_field_names(base: Message, update: Message) -> list[str]:
    """Which field names the update would write onto the base."""

    _require_same_schema(base, update)
    return present_fields(update)


def merge_diff(base: Message, update: Message) -> dict[str, tuple[object, object]]:
    """Map of field name -> (old, new) for fields the merge would change."""

    merged = merge(base, update)
    diff: dict[str, tuple[object, object]] = {}
    for name in base.schema.field_names():
        before = base.get(name)
        after = merged.get(name)
        if before != after:
            diff[name] = (before, after)
    return diff


def overlay(base: Message, named_update: dict[str, object]) -> Message:
    """Merge a base with values supplied as a plain name->value dict."""

    _require_named_fields(base, named_update)
    update = base.copy()
    update._assigned.clear()
    for name, value in named_update.items():
        update.set(name, value)
    return merge(base, update)


def _require_same_schema(base: Message, update: Message) -> None:
    if base.schema.name != update.schema.name:
        raise ValueError("cannot merge messages of different schemas")
    if base.schema.field_names() != update.schema.field_names():
        raise ValueError("schema field layout mismatch")


def _require_named_fields(base: Message, named: dict[str, object]) -> None:
    for name in named:
        if not base.schema.has_field(name):
            raise KeyError(f"unknown field {name}")


def fold_summary(base: Message, update: Message) -> str:
    names = merged_field_names(base, update)
    if not names:
        return f"merge {update.schema.name}: nothing to apply"
    return f"merge {update.schema.name}: applied {', '.join(names)}"

