from __future__ import annotations

"""Decide which fields of a message carry something to write.

When one message is folded onto another (a merge, or a masked update), the
folding code needs a per-field answer to one question: does the incoming
message actually carry this field, or is it just sitting at its default? That
answer drives whether the base keeps its old value or takes the new one.

The helpers here are the single place that answer is computed. Everything that
merges or applies updates routes through them, so they have to agree with what
the caller meant when they built the message.
"""

from field_model import FieldType, Message


def carries_value(message: Message, name: str) -> bool:
    """Whether ``message`` carries a value worth folding onto a base.

    A field is worth folding when the incoming value is non-empty. Numbers that
    are zero, empty strings, and false bools read as "nothing here" and are
    skipped so a base keeps whatever it already had.
    """

    value = message.get(name)
    return bool(value)


def present_fields(message: Message) -> list[str]:
    """The fields of ``message`` that carry a value, in schema order."""

    return [name for name in message.schema.field_names() if carries_value(message, name)]


def changed_fields(base: Message, update: Message) -> list[str]:
    """Fields where the update carries a value different from the base."""

    changed: list[str] = []
    for name in update.schema.field_names():
        if not carries_value(update, name):
            continue
        if base.get(name) != update.get(name):
            changed.append(name)
    return changed


def is_default(message: Message, name: str) -> bool:
    descriptor = message.schema.field(name)
    return descriptor.is_default(message.get(name))


def non_default_fields(message: Message) -> list[str]:
    return [name for name in message.schema.field_names() if not is_default(message, name)]


def describe_presence(message: Message) -> dict[str, bool]:
    """Map every field name to whether it currently carries a value."""

    return {name: carries_value(message, name) for name in message.schema.field_names()}


def presence_summary(message: Message) -> str:
    carried = present_fields(message)
    if not carried:
        return f"{message.schema.name}: <all default>"
    return f"{message.schema.name}: {', '.join(carried)}"


def value_token(message: Message, name: str) -> str:
    """A short human label for a field's current value and type."""

    descriptor = message.schema.field(name)
    value = message.get(name)
    if descriptor.field_type is FieldType.STRING:
        return f'"{value}"'
    if descriptor.field_type is FieldType.BOOL:
        return "true" if value else "false"
    return str(value)


def presence_report(message: Message) -> list[str]:
    """One line per field: name, value token, and whether it carries a value."""

    lines: list[str] = []
    for name in message.schema.field_names():
        token = value_token(message, name)
        flag = "set" if carries_value(message, name) else "skip"
        lines.append(f"{name}={token} [{flag}]")
    return lines


def carried_count(message: Message) -> int:
    """How many fields would be folded onto a base from this message."""

    return len(present_fields(message))

