from __future__ import annotations

"""Concrete schemas and builders for the examples and tests.

The running example is a ``Product`` message used by an internal catalog
service: an int32 ``price_cents``, a string ``name``, a bool ``active``, and an
enum ``visibility``. Each of these has a meaningful default that a caller might
legitimately want to set: price back to zero (a freebie), name cleared, the
product deactivated, visibility reset to the zero-valued constant.
"""

from field_model import FieldDescriptor, FieldType, Message, MessageSchema, new_message


# Visibility enum constants (proto3 enums must have a zero-valued entry).
VISIBILITY_UNSPECIFIED = 0
VISIBILITY_PUBLIC = 1
VISIBILITY_PRIVATE = 2


def product_schema() -> MessageSchema:
    return MessageSchema(
        name="Product",
        fields=(
            FieldDescriptor("price_cents", 1, FieldType.INT32),
            FieldDescriptor("name", 2, FieldType.STRING),
            FieldDescriptor("active", 3, FieldType.BOOL),
            FieldDescriptor("visibility", 4, FieldType.ENUM),
        ),
    )


def build_product(
    *,
    price_cents: int | None = None,
    name: str | None = None,
    active: bool | None = None,
    visibility: int | None = None,
) -> Message:
    """Build a Product, marking only the explicitly passed fields as assigned."""

    schema = product_schema()
    assignments: dict[str, object] = {}
    if price_cents is not None:
        assignments["price_cents"] = price_cents
    if name is not None:
        assignments["name"] = name
    if active is not None:
        assignments["active"] = active
    if visibility is not None:
        assignments["visibility"] = visibility
    return new_message(schema, **assignments)


def empty_product() -> Message:
    """A Product with no fields assigned (everything at its default)."""

    return Message(schema=product_schema())


def sample_product() -> Message:
    return build_product(
        price_cents=1999,
        name="Wireless Mouse",
        active=True,
        visibility=VISIBILITY_PUBLIC,
    )


# A second schema with different field numbers, used to exercise number-keyed wire encoding.
def account_schema() -> MessageSchema:
    return MessageSchema(
        name="Account",
        fields=(
            FieldDescriptor("balance_cents", 7, FieldType.INT32),
            FieldDescriptor("handle", 12, FieldType.STRING),
            FieldDescriptor("verified", 3, FieldType.BOOL),
        ),
    )


def build_account(
    *,
    balance_cents: int | None = None,
    handle: str | None = None,
    verified: bool | None = None,
) -> Message:
    schema = account_schema()
    assignments: dict[str, object] = {}
    if balance_cents is not None:
        assignments["balance_cents"] = balance_cents
    if handle is not None:
        assignments["handle"] = handle
    if verified is not None:
        assignments["verified"] = verified
    return new_message(schema, **assignments)


def field_numbers(schema: MessageSchema) -> dict[str, int]:
    return {descriptor.name: descriptor.number for descriptor in schema.fields}


def describe_schema(schema: MessageSchema) -> str:
    parts = [f"{d.name}={d.number}:{d.field_type.value}" for d in schema.fields]
    return f"{schema.name}({', '.join(parts)})"

