"""Partial-update workflow with a field mask, plus a small record store.

A field mask is an explicit list of field names a caller wants written. The
semantics are: for every field named in the mask, take the update's value and
write it onto the base, even if that value is the type default. Fields outside
the mask are left exactly as the base had them. This is how a PATCH-style API
lets a caller set ``price`` to ``0`` or ``name`` to ``""`` on purpose without
touching anything else.

``RecordStore`` keeps the latest message per key and exposes the masked-update
entry point that an RPC handler would call.
"""

from field_model import Message, MessageSchema, new_message
from presence import carries_value
from merge_engine import merge


def normalize_mask(schema: MessageSchema, field_mask: list[str] | None) -> list[str]:
    if field_mask is None:
        return list(schema.field_names())
    seen: list[str] = []
    for name in field_mask:
        if not schema.has_field(name):
            raise KeyError(f"unknown field in mask: {name}")
        if name not in seen:
            seen.append(name)
    return seen


def apply_update(
    base: Message,
    update: Message,
    field_mask: list[str] | None = None,
) -> Message:
    """Apply only the masked fields of ``update`` onto ``base``.

    With no mask, this behaves like a full merge of carried fields. With a
    mask, only the named fields are considered for writing.
    """

    if base.schema.name != update.schema.name:
        raise ValueError("cannot update across different schemas")

    mask = normalize_mask(base.schema, field_mask)
    if field_mask is None:
        return merge(base, update)

    result = base.copy()
    for name in mask:
        if carries_value(update, name):
            result.set(name, update.get(name))
    return result


def apply_named_update(
    base: Message,
    named: dict[str, object],
    field_mask: list[str] | None = None,
) -> Message:
    """Build an update message from a name->value dict, then apply it."""

    update = new_message(base.schema, **named)
    mask = field_mask if field_mask is not None else list(named.keys())
    return apply_update(base, update, mask)


def changed_by_mask(base: Message, update: Message, field_mask: list[str]) -> list[str]:
    result = apply_update(base, update, field_mask)
    return [name for name in base.schema.field_names() if base.get(name) != result.get(name)]


class RecordStore:
    def __init__(self, schema: MessageSchema) -> None:
        self._schema = schema
        self._rows: dict[str, Message] = {}

    @property
    def schema(self) -> MessageSchema:
        return self._schema

    def put(self, key: str, message: Message) -> Message:
        if message.schema.name != self._schema.name:
            raise ValueError("message schema does not match store schema")
        self._rows[key] = message.copy()
        return self._rows[key]

    def get(self, key: str) -> Message | None:
        row = self._rows.get(key)
        return row.copy() if row is not None else None

    def require(self, key: str) -> Message:
        row = self._rows.get(key)
        if row is None:
            raise KeyError(f"no record for {key}")
        return row.copy()

    def has(self, key: str) -> bool:
        return key in self._rows

    def patch(
        self,
        key: str,
        update: Message,
        field_mask: list[str] | None = None,
    ) -> Message:
        """Apply a masked update to the stored record and persist the result."""

        current = self.require(key)
        updated = apply_update(current, update, field_mask)
        self._rows[key] = updated.copy()
        return self._rows[key]

    def patch_named(
        self,
        key: str,
        named: dict[str, object],
        field_mask: list[str] | None = None,
    ) -> Message:
        current = self.require(key)
        updated = apply_named_update(current, named, field_mask)
        self._rows[key] = updated.copy()
        return self._rows[key]

    def value_at(self, key: str, name: str) -> object:
        return self.require(key).get(name)

    def keys(self) -> list[str]:
        return list(self._rows)

