from __future__ import annotations

"""Serialize a message to a wire-like dict and back.

This mimics one real proto3 trait: on the wire, scalar fields holding their
default value are simply not written. The encoded form is keyed by field
number (an int), and only fields whose value differs from the type default
appear. Decoding fills every absent field back in with its default, so the
round trip reproduces the same values a reader would observe.

Note that the wire form deliberately drops defaults; this is correct and
expected for proto3 scalars. It is not the same question as whether a field was
explicitly assigned by a caller, which the merge and update paths care about.
"""

from field_model import FieldType, Message, MessageSchema, new_message


def encode(message: Message) -> dict[int, object]:
    """Encode to a {field_number: value} dict, omitting default-valued scalars."""

    wire: dict[int, object] = {}
    for descriptor in message.schema.fields:
        value = message.get(descriptor.name)
        if descriptor.is_default(value):
            # proto3: default scalars are not emitted on the wire.
            continue
        wire[descriptor.number] = value
    return wire


def decode(schema: MessageSchema, wire: dict[int, object]) -> Message:
    """Decode a wire dict back into a message, filling absent fields with defaults."""

    by_number = {descriptor.number: descriptor for descriptor in schema.fields}
    assignments: dict[str, object] = {}
    for number, value in wire.items():
        descriptor = by_number.get(number)
        if descriptor is None:
            raise KeyError(f"unknown field number {number}")
        assignments[descriptor.name] = value
    message = new_message(schema, **assignments)
    return message


def encoded_field_numbers(message: Message) -> list[int]:
    return sorted(encode(message).keys())


def encoded_size(message: Message) -> int:
    """Number of fields that would be written to the wire."""

    return len(encode(message))


def wire_to_named(schema: MessageSchema, wire: dict[int, object]) -> dict[str, object]:
    """Translate a wire dict (keyed by number) into a name-keyed dict."""

    by_number = {descriptor.number: descriptor for descriptor in schema.fields}
    named: dict[str, object] = {}
    for number, value in wire.items():
        descriptor = by_number.get(number)
        if descriptor is None:
            raise KeyError(f"unknown field number {number}")
        named[descriptor.name] = value
    return named


def named_to_wire(schema: MessageSchema, named: dict[str, object]) -> dict[int, object]:
    wire: dict[int, object] = {}
    for name, value in named.items():
        descriptor = schema.field(name)
        if descriptor.is_default(value):
            continue
        wire[descriptor.number] = value
    return wire


def roundtrip(message: Message) -> Message:
    """Encode then decode; the observed field values must match."""

    return decode(message.schema, encode(message))


def values_equal(left: Message, right: Message) -> bool:
    """Whether two messages of the same schema observe the same field values."""

    if left.schema.name != right.schema.name:
        return False
    for name in left.schema.field_names():
        if left.get(name) != right.get(name):
            return False
    return True


def encode_for_type(field_type: FieldType, value: object, number: int) -> dict[int, object]:
    """Encode a single typed scalar (helper for targeted tests)."""

    from field_model import FieldDescriptor

    descriptor = FieldDescriptor(name="f", number=number, field_type=field_type)
    if descriptor.is_default(value):
        return {}
    return {number: value}

